-- Phase: managed-role-bootstrap
CREATE ROLE greenfield_assessment_review_app LOGIN NOINHERIT NOSUPERUSER NOBYPASSRLS NOCREATEROLE NOCREATEDB NOREPLICATION PASSWORD NULL;
CREATE ROLE greenfield_assessment_review_runtime NOLOGIN NOINHERIT NOSUPERUSER NOBYPASSRLS NOCREATEROLE NOCREATEDB NOREPLICATION;
GRANT CONNECT ON DATABASE postgres TO greenfield_assessment_review_app;
GRANT greenfield_assessment_review_runtime TO greenfield_assessment_review_app WITH ADMIN FALSE GRANTED BY postgres;
GRANT greenfield_assessment_review_runtime TO greenfield_assessment_review_app WITH INHERIT FALSE GRANTED BY postgres;
GRANT greenfield_assessment_review_runtime TO greenfield_assessment_review_app WITH SET TRUE GRANTED BY postgres;
GRANT greenfield_report_card_authority_owner TO postgres WITH ADMIN FALSE GRANTED BY postgres;
GRANT greenfield_report_card_authority_owner TO postgres WITH INHERIT FALSE GRANTED BY postgres;
GRANT greenfield_report_card_authority_owner TO postgres WITH SET TRUE GRANTED BY postgres;
GRANT greenfield_assessment_review_runtime TO postgres WITH ADMIN FALSE GRANTED BY postgres;
GRANT greenfield_assessment_review_runtime TO postgres WITH INHERIT FALSE GRANTED BY postgres;
GRANT greenfield_assessment_review_runtime TO postgres WITH SET TRUE GRANTED BY postgres;

-- Phase: reviewed-private-policies-and-guard
GRANT USAGE ON SCHEMA "public" TO "greenfield_assessment_review_runtime";
CREATE FUNCTION "public"."guard_assessment_review_writes"() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF current_user='greenfield_assessment_review_runtime' AND NOT (TG_OP='INSERT' AND TG_TABLE_NAME IN ('assessment_source_versions','assessment_teacher_reviews','assessment_finalizations','assessment_audit','assessment_operation_receipts')) THEN RAISE EXCEPTION 'review runtime cannot mutate existing rows' USING ERRCODE='42501'; END IF;
 RETURN NULL; END $$;
REVOKE ALL ON FUNCTION "public"."guard_assessment_review_writes"() FROM PUBLIC,"greenfield_assessment_review_runtime","greenfield_assessment_review_app";
GRANT SELECT, UPDATE(id) ON "public"."schools" TO "greenfield_assessment_review_runtime";
CREATE POLICY assessment_review_clamp ON "public"."schools" AS RESTRICTIVE FOR ALL TO "greenfield_assessment_review_runtime" USING (id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid) WITH CHECK (id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid);
CREATE POLICY assessment_review_read ON "public"."schools" FOR SELECT TO "greenfield_assessment_review_runtime" USING (id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid);
CREATE POLICY assessment_review_lock ON "public"."schools" FOR UPDATE TO "greenfield_assessment_review_runtime" USING (id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid) WITH CHECK (false);
CREATE TRIGGER assessment_review_service_guard BEFORE INSERT OR UPDATE OR DELETE OR TRUNCATE ON "public"."schools" FOR EACH STATEMENT EXECUTE FUNCTION "public"."guard_assessment_review_writes"();
