-- Phase: new-guard-default-acl-reset
DO $review_guard_acl$ DECLARE item record;BEGIN FOR item IN SELECT a.grantee FROM pg_catalog.pg_proc p CROSS JOIN LATERAL pg_catalog.aclexplode(CASE WHEN cardinality(p.proacl)>0 THEN p.proacl END) a WHERE p.oid='public.guard_assessment_review_writes()'::regprocedure AND a.grantee<>p.proowner LOOP EXECUTE format('REVOKE ALL ON FUNCTION public.guard_assessment_review_writes() FROM %s',CASE WHEN item.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(item.grantee)) END);END LOOP;END $review_guard_acl$;

-- Phase: owner-authorized-complete-helper-grant
SET LOCAL ROLE greenfield_report_card_authority_owner;
GRANT EXECUTE ON FUNCTION public.lock_report_card_actor(uuid) TO greenfield_assessment_review_runtime;
RESET ROLE;

-- Phase: switched-role-authority-and-denial-probes
SET LOCAL ROLE greenfield_assessment_review_runtime;
DO $review_role_probes$ DECLARE name text;denied boolean;BEGIN
 IF current_user<>'greenfield_assessment_review_runtime' OR session_user<>'postgres' THEN RAISE EXCEPTION 'Exact switched review role required for managed probes';END IF;
 IF (SELECT count(*) FROM public.lock_report_card_actor('6448c80e-ed5c-41a4-bcf5-39fd0dfb5b61'::uuid) WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid AND role='teacher' AND active_membership_count=1)<>1 OR (SELECT count(*) FROM public.lock_report_card_actor('355d5e24-41f6-4544-9536-38ecb461b651'::uuid) WHERE school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid AND role='admin' AND active_membership_count=1)<>1 THEN RAISE EXCEPTION 'Fictional teacher/admin complete authority probe failed';END IF;
 IF EXISTS(SELECT 1 FROM public.lock_report_card_actor(NULL::uuid)) OR EXISTS(SELECT 1 FROM public.lock_report_card_actor('ee29b64a-37fe-44a1-9285-af6a37088415'::uuid)) THEN RAISE EXCEPTION 'Unbound/bursar academic authority must deny';END IF;
 FOREACH name IN ARRAY ARRAY['schools','school_users','memberships','academic_sessions','terms','academic_levels','academic_sections','classes','students','enrollments','teacher_class_assignments','assessment_subjects','assessment_config_versions','assessment_scopes','assessment_subject_roster','assessment_teacher_subjects','assessment_scores','assessment_source_versions','assessment_teacher_reviews','assessment_finalizations','assessment_audit','assessment_operation_receipts','assessment_source_write_gate'] LOOP denied:=false;BEGIN EXECUTE format('UPDATE public.%I SET id=id WHERE false',name);EXCEPTION WHEN insufficient_privilege OR raise_exception THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Zero-row review mutation allowed: %',name;END IF;END LOOP;
 FOREACH name IN ARRAY ARRAY['report_cards','report_card_snapshots','report_card_audit','report_card_operation_receipts','report_card_releases','assessment_source_write_claims'] LOOP denied:=false;BEGIN EXECUTE format('SELECT 1 FROM public.%I WHERE false',name);EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Protected report/claims read allowed: %',name;END IF;END LOOP;
END $review_role_probes$;
RESET ROLE;

-- Phase: exact-temporary-grant-cleanup
REVOKE greenfield_assessment_review_runtime FROM postgres GRANTED BY postgres;
REVOKE greenfield_report_card_authority_owner FROM postgres GRANTED BY postgres;

-- Phase: in-transaction-verification
DO $review_verify$ DECLARE role_name text;relation_name text;permission_name text;column_row record;allowed boolean;signature_name text;BEGIN
 IF (SELECT count(*) FROM pg_catalog.pg_roles WHERE rolname IN ('greenfield_assessment_review_app','greenfield_assessment_review_runtime') AND NOT rolsuper AND NOT rolbypassrls AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolreplication AND NOT rolinherit AND rolcanlogin=(rolname='greenfield_assessment_review_app'))<>2 OR EXISTS(SELECT 1 FROM pg_catalog.pg_shdepend d JOIN pg_catalog.pg_roles r ON r.oid=d.refobjid WHERE d.refclassid='pg_catalog.pg_authid'::regclass AND d.deptype='o' AND r.rolname IN ('greenfield_assessment_review_app','greenfield_assessment_review_runtime')) THEN RAISE EXCEPTION 'New review role flags/ownership invalid';END IF;
 IF (SELECT count(*) FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles r ON r.oid=m.roleid WHERE r.rolname IN ('greenfield_assessment_review_app','greenfield_assessment_review_runtime'))<>3 OR (SELECT count(*) FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles r ON r.oid=m.roleid JOIN pg_catalog.pg_roles u ON u.oid=m.member JOIN pg_catalog.pg_roles g ON g.oid=m.grantor WHERE r.rolname IN ('greenfield_assessment_review_app','greenfield_assessment_review_runtime') AND u.rolname='postgres' AND m.admin_option AND NOT m.inherit_option AND NOT m.set_option AND g.rolsuper)<>2 OR (SELECT count(*) FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles u ON u.oid=m.member WHERE u.rolname IN ('greenfield_assessment_review_app','greenfield_assessment_review_runtime'))<>1 OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members m JOIN pg_catalog.pg_roles u ON u.oid=m.member JOIN pg_catalog.pg_roles r ON r.oid=m.roleid WHERE u.rolname='greenfield_assessment_review_app' AND r.rolname='greenfield_assessment_review_runtime' AND m.set_option AND NOT m.inherit_option AND NOT m.admin_option) THEN RAISE EXCEPTION 'Review SET-only/bootstrap graph invalid';END IF;
 IF pg_has_role(current_user,'greenfield_report_card_authority_owner','SET') OR pg_has_role(current_user,'greenfield_assessment_review_runtime','SET') THEN RAISE EXCEPTION 'Temporary operator SET grant remains';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_proc WHERE oid='public.guard_assessment_review_writes()'::regprocedure AND proowner=(SELECT oid FROM pg_catalog.pg_roles WHERE rolname='postgres') AND NOT prosecdef AND prorettype='pg_catalog.trigger'::regtype AND pronargs=0 AND prosrc=' BEGIN
 IF current_user=''greenfield_assessment_review_runtime'' AND NOT (TG_OP=''INSERT'' AND TG_TABLE_NAME IN (''assessment_source_versions'',''assessment_teacher_reviews'',''assessment_finalizations'',''assessment_audit'',''assessment_operation_receipts'')) THEN RAISE EXCEPTION ''review runtime cannot mutate existing rows'' USING ERRCODE=''42501''; END IF;
 RETURN NULL; END ' AND proconfig=ARRAY['search_path=pg_catalog']) OR EXISTS(SELECT 1 FROM pg_catalog.pg_proc p CROSS JOIN LATERAL pg_catalog.aclexplode(CASE WHEN cardinality(p.proacl)>0 THEN p.proacl END) a WHERE p.oid='public.guard_assessment_review_writes()'::regprocedure AND a.grantee<>p.proowner) THEN RAISE EXCEPTION 'New private guard body/owner/settings/ACL invalid';END IF;
 IF (SELECT count(*) FROM pg_catalog.pg_trigger tr JOIN pg_catalog.pg_class c ON c.oid=tr.tgrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND tr.tgname='assessment_review_service_guard' AND tr.tgfoid='public.guard_assessment_review_writes()'::regprocedure AND tr.tgenabled='O' AND tr.tgtype=62 AND c.relname IN ('schools','school_users','memberships','academic_sessions','terms','academic_levels','academic_sections','classes','students','enrollments','teacher_class_assignments','assessment_subjects','assessment_config_versions','assessment_scopes','assessment_subject_roster','assessment_teacher_subjects','assessment_scores','assessment_source_versions','assessment_teacher_reviews','assessment_finalizations','assessment_audit','assessment_operation_receipts','assessment_source_write_gate'))<>23 THEN RAISE EXCEPTION 'Exact zero-row review statement guards missing';END IF;
 IF (SELECT count(*) FROM pg_catalog.pg_policies WHERE schemaname='public' AND policyname IN ('assessment_review_clamp','assessment_review_read','assessment_review_lock','assessment_review_insert'))<>74 OR EXISTS(SELECT 1 FROM pg_catalog.pg_policies WHERE schemaname='public' AND policyname IN ('assessment_review_clamp','assessment_review_read','assessment_review_lock','assessment_review_insert') AND roles IS DISTINCT FROM ARRAY['greenfield_assessment_review_runtime']::name[]) THEN RAISE EXCEPTION 'Exact review-only policies missing';END IF;
 FOREACH role_name IN ARRAY ARRAY['greenfield_assessment_review_app','greenfield_assessment_review_runtime'] LOOP
 IF has_schema_privilege(role_name,'public','CREATE') OR has_schema_privilege(role_name,'auth','USAGE') OR has_function_privilege(role_name,'public.guard_assessment_review_writes()','EXECUTE') THEN RAISE EXCEPTION 'Unexpected review schema/guard access';END IF;
 FOR relation_name IN SELECT c.relname FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p') LOOP
 FOREACH permission_name IN ARRAY ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER','MAINTAIN'] LOOP
 allowed:=role_name='greenfield_assessment_review_runtime' AND CASE WHEN permission_name='SELECT' THEN relation_name=ANY(ARRAY['schools','school_users','memberships','academic_sessions','terms','academic_levels','academic_sections','classes','students','enrollments','teacher_class_assignments','assessment_subjects','assessment_config_versions','assessment_scopes','assessment_subject_roster','assessment_teacher_subjects','assessment_scores','assessment_source_versions','assessment_teacher_reviews','assessment_finalizations','assessment_audit','assessment_operation_receipts','assessment_source_write_gate']) WHEN permission_name='INSERT' THEN relation_name=ANY(ARRAY['assessment_source_versions','assessment_teacher_reviews','assessment_finalizations','assessment_audit','assessment_operation_receipts']) ELSE false END;
 IF has_table_privilege(role_name,'public.'||relation_name,permission_name) IS DISTINCT FROM allowed THEN RAISE EXCEPTION 'Unexpected review table privilege: %.%.%',role_name,relation_name,permission_name;END IF;
 END LOOP;END LOOP;
 FOR column_row IN SELECT c.relname,a.attname FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace JOIN pg_catalog.pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped WHERE n.nspname='public' AND c.relkind IN ('r','p') LOOP
 FOREACH permission_name IN ARRAY ARRAY['SELECT','INSERT','UPDATE','REFERENCES'] LOOP
 allowed:=role_name='greenfield_assessment_review_runtime' AND CASE WHEN permission_name='SELECT' THEN column_row.relname=ANY(ARRAY['schools','school_users','memberships','academic_sessions','terms','academic_levels','academic_sections','classes','students','enrollments','teacher_class_assignments','assessment_subjects','assessment_config_versions','assessment_scopes','assessment_subject_roster','assessment_teacher_subjects','assessment_scores','assessment_source_versions','assessment_teacher_reviews','assessment_finalizations','assessment_audit','assessment_operation_receipts','assessment_source_write_gate']) WHEN permission_name='INSERT' THEN column_row.relname=ANY(ARRAY['assessment_source_versions','assessment_teacher_reviews','assessment_finalizations','assessment_audit','assessment_operation_receipts']) WHEN permission_name='UPDATE' THEN column_row.relname=ANY(ARRAY['schools','school_users','memberships','academic_sessions','terms','academic_levels','academic_sections','classes','students','enrollments','teacher_class_assignments','assessment_subjects','assessment_config_versions','assessment_scopes','assessment_subject_roster','assessment_teacher_subjects','assessment_scores','assessment_source_versions','assessment_teacher_reviews','assessment_finalizations','assessment_audit','assessment_operation_receipts','assessment_source_write_gate']) AND column_row.attname='id' ELSE false END;
 IF has_column_privilege(role_name,'public.'||column_row.relname,column_row.attname,permission_name) IS DISTINCT FROM allowed THEN RAISE EXCEPTION 'Unexpected review column privilege';END IF;
 END LOOP;
 END LOOP;
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE CASE WHEN n.nspname='public' AND c.relkind='S' THEN has_sequence_privilege(role_name,c.oid,'USAGE,SELECT,UPDATE') ELSE false END) THEN RAISE EXCEPTION 'Unexpected review sequence access';END IF;
 FOREACH signature_name IN ARRAY ARRAY['public.assessment_invalidate_parent_rows()','public.assessment_invalidate_source_rows()','public.assessment_lock_source_write()','public.assessment_mark_source_scope(uuid)','public.assessment_reject_source_truncate()','public.deny_attendance_history_change()','public.lock_report_card_actor(uuid)','public.lock_report_card_authority_write_gate()','public.lock_report_card_membership_actor_anchor()','public.read_attendance(uuid,text,date)','public.report_card_guard_release_history()','public.report_card_reject_history()','public.report_card_request_auth_uid()','public.report_card_restrict_runtime_writes()','public.resolve_report_card_actor()','public.resolve_staging_staff_account()','public.save_assessment_subject_scores(uuid,jsonb)','public.save_attendance(uuid,jsonb)'] LOOP
 allowed:=role_name='greenfield_assessment_review_runtime' AND signature_name='public.lock_report_card_actor(uuid)';
 IF has_function_privilege(role_name,signature_name,'EXECUTE') IS DISTINCT FROM allowed THEN RAISE EXCEPTION 'Unexpected review helper/API privilege';END IF;
 END LOOP;END LOOP;
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_proc p CROSS JOIN LATERAL pg_catalog.aclexplode(CASE WHEN cardinality(p.proacl)>0 THEN p.proacl END) a JOIN pg_catalog.pg_roles r ON r.oid=a.grantee WHERE p.oid IN (to_regprocedure('public.assessment_invalidate_parent_rows()'),to_regprocedure('public.assessment_invalidate_source_rows()'),to_regprocedure('public.assessment_lock_source_write()'),to_regprocedure('public.assessment_mark_source_scope(uuid)'),to_regprocedure('public.assessment_reject_source_truncate()'),to_regprocedure('public.deny_attendance_history_change()'),to_regprocedure('public.lock_report_card_actor(uuid)'),to_regprocedure('public.lock_report_card_authority_write_gate()'),to_regprocedure('public.lock_report_card_membership_actor_anchor()'),to_regprocedure('public.read_attendance(uuid,text,date)'),to_regprocedure('public.report_card_guard_release_history()'),to_regprocedure('public.report_card_reject_history()'),to_regprocedure('public.report_card_request_auth_uid()'),to_regprocedure('public.report_card_restrict_runtime_writes()'),to_regprocedure('public.resolve_report_card_actor()'),to_regprocedure('public.resolve_staging_staff_account()'),to_regprocedure('public.save_assessment_subject_scores(uuid,jsonb)'),to_regprocedure('public.save_attendance(uuid,jsonb)')) AND r.rolname IN ('greenfield_assessment_review_app','greenfield_assessment_review_runtime') AND NOT (r.rolname='greenfield_assessment_review_runtime' AND p.oid='public.lock_report_card_actor(uuid)'::regprocedure AND a.privilege_type='EXECUTE' AND NOT a.is_grantable)) THEN RAISE EXCEPTION 'Unexpected new-role helper grant/option';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_temp.greenfield_review_install_baseline b WHERE b.data_state IS NOT DISTINCT FROM (SELECT jsonb_object_agg(relation,jsonb_build_object('rows',n,'marker',marker)) FROM (SELECT 'academic_levels'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(r)::text),'' ORDER BY to_jsonb(r)::text),'')) AS marker FROM public.academic_levels r WHERE r.school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'academic_sections'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(r)::text),'' ORDER BY to_jsonb(r)::text),'')) AS marker FROM public.academic_sections r WHERE r.school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'academic_sessions'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(r)::text),'' ORDER BY to_jsonb(r)::text),'')) AS marker FROM public.academic_sessions r WHERE r.school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'assessment_audit'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(r)::text),'' ORDER BY to_jsonb(r)::text),'')) AS marker FROM public.assessment_audit r WHERE r.school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'assessment_config_versions'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(r)::text),'' ORDER BY to_jsonb(r)::text),'')) AS marker FROM public.assessment_config_versions r WHERE r.school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'assessment_finalizations'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(r)::text),'' ORDER BY to_jsonb(r)::text),'')) AS marker FROM public.assessment_finalizations r WHERE r.school_id='0c594571-74c5-46fe-a835-a9b217a3a199'::uuid UNION ALL SELECT 'assessment_operation_receipts'::text AS relation,count(*)::bigint AS n,md5(COALESCE(string_agg(md5(to_jsonb(r)::text),'' ORDER BY to_jsonb(r)::text),'')) AS marker FROM public.